57	
58	    @Transactional(readOnly = true)
59	    public List<Person> list(String sheetId) {
60	        return people.findBySheetIdOrderByIdAsc(sheetId);
61	    }
62	
63	    /** The sheet's today: the date the grade a person shows is in force on. */
64	    @Transactional(readOnly = true)
65	    public LocalDate today(String sheetId) {
66	        return sheets.today(sheetId);
67	    }
68	
69	    @Transactional(readOnly = true)
70	    public Person get(String sheetId, long id) {
71	        return people.findByIdAndSheetId(id, sheetId)
72	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
