78	        return statements.findBySheetIdOrderByIdAsc(sheetId).stream()
79	                .collect(Collectors.groupingBy(PersonStatement::getPersonId,
80	                        Collectors.collectingAndThen(Collectors.toList(), StatementSummary::of)));
81	    }
