83	    @Transactional(readOnly = true)
84	    public StatementSummary statementSummary(long personId) {
85	        return StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId));
86	    }
87	
88	    /** Each person's patron ids in the order they were named, by person id; a person with none is missing. */
89	    @Transactional(readOnly = true)
90	    public Map<Long, List<Long>> patronIds(String sheetId) {
91	        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
92	                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
93	                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
94	    }
95	
96	    @Transactional(readOnly = true)
97	    public List<Long> patronIds(long personId) {
98	        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
99	    }
