101	    /** The ids of the people on the sheet the user watches. */
102	    @Transactional(readOnly = true)
103	    public Set<Long> watchedIds(String sheetId, String user) {
104	        return watches.findBySheetIdAndUserName(sheetId, user).stream().map(PersonWatch::getPersonId)
105	                .collect(Collectors.toSet());
106	    }
107	
108	    @Transactional(readOnly = true)
109	    public boolean isWatching(long personId, String user) {
110	        return watches.existsByPersonIdAndUserName(personId, user);
111	    }
112	
113	    /** Start (on) or stop watching the person as the user; already so, nothing changes; refused
114	     *  (403) on an archived sheet. */
115	    @Transactional
116	    public Person watch(String sheetId, String user, long id, boolean on) {
117	        if (sheets.archived(sheetId)) {
118	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived: nothing on it may change");
119	        }
120	        Person person = people.findForUpdate(id, sheetId)
121	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
122	        if (on) {
123	            if (watches.existsByPersonIdAndUserName(person.getId(), user)) {
124	                return person;
125	            }
126	            watches.saveAndFlush(new PersonWatch(sheetId, person.getId(), user));
127	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
128	        } else if (watches.deleteByPersonIdAndUserName(person.getId(), user) > 0) {
129	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
130	        }
131	        return person;
132	    }
133	
134	    /** Name another person on the sheet as the person's patron; refused for the person themselves
135	     *  and for a patron they already have. */
136	    @Transactional
137	    public Person addPatron(String sheetId, String user, long id, long patronId) {
138	        Person person = people.findForUpdate(id, sheetId)
139	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
140	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
141	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
142	        if (person.getId().equals(patron.getId())) {
143	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be their own patron");
144	        }
145	        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
146	            throw patronAlready();
147	        }
148	        try {
149	            patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
150	        } catch (DataIntegrityViolationException e) {
151	            throw patronAlready(); // named by another user at the same moment
152	        }
153	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
154	                + " name=" + person.getName() + " patron=" + patron.getName());
155	        return person;
156	    }
157	
158	    /** Give the person an alias (trimmed); refused when blank, or when it equals, ignoring case, any
159	     *  name or alias on the sheet. */
160	    @Transactional
161	    public Person addAlias(String sheetId, String user, long id, String alias) {
162	        if (sheets.archived(sheetId)) {
163	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived: nothing on it may change");
164	        }
165	        Person person = people.findForUpdate(id, sheetId)
166	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
167	        String trimmed = alias == null ? "" : alias.trim();
168	        if (trimmed.isEmpty()) {
169	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "An alias may not be blank");
170	        }
171	        requireUnusedName(sheetId, null, trimmed);
172	        person.addAlias(trimmed);
173	        try {
174	            people.flush();
175	        } catch (DataIntegrityViolationException e) {
176	            throw nameInUse(); // given by another user at the same moment
177	        } catch (ObjectOptimisticLockingFailureException e) {
178	            throw savedByAnother(); // saved by another user at the same moment
179	        }
180	        audit.recordOnCommit("PERSON_ALIAS_ADDED sheet=" + sheetId + " by=" + user
181	                + " name=" + person.getName() + " alias=" + trimmed);
182	        return person;
183	    }
