185	    /** Add a person to the sheet (the sheet is created first if it was never loaded); {@code contact}
186	     *  (trimmed and lower-cased, null: none) is refused when another person on the sheet has it. */
187	    @Transactional
188	    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
189	        sheets.load(sheetId, user);
190	        RollupService.Snapshot before = rollup.snapshot(sheetId);
191	        String trimmed = name.trim();
192	        requireUnusedName(sheetId, null, trimmed);
193	        requireUnusedContact(sheetId, null, contact);
194	        Person person;
195	        try {
196	            Person fresh = new Person(sheetId, trimmed, grade);
197	            fresh.setTerms(terms);
198	            fresh.setContact(contact);
199	            person = people.saveAndFlush(fresh);
200	        } catch (DataIntegrityViolationException e) {
201	            throw inUse(e); // added by another user at the same moment
202	        }
203	        record("PERSON_ADDED", sheetId, user, person, sheets.today(sheetId),
204	                (terms == null ? "" : termsField(terms)) + (contact == null ? "" : contactField(contact)));
205	        rollup.recordChanges(sheetId, user, before);
206	        return person;
207	    }
208	
209	    /** Save a person; refused when {@code version} (the one the editor loaded) is no longer the stored one.
210	     *  The grade is recorded from {@code gradeFrom} (null: the sheet's today), keeping those already
211	     *  recorded; with no from-date, a grade the same as the one in force on the sheet's today records nothing.
212	     *  The person's own terms become {@code terms} (null: none), and their contact {@code contact}
213	     *  (null: none), refused when another person on the sheet has it. */
214	    @Transactional
215	    public Person update(String sheetId, String user, long id, Long version, String name, String grade,
216	            LocalDate gradeFrom, Integer terms, String contact) {
217	        Person person = people.findByIdAndSheetId(id, sheetId)
218	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
219	        if (version == null || version != person.getVersion()) {
220	            throw savedByAnother();
221	        }
222	        RollupService.Snapshot before = rollup.snapshot(sheetId);
223	        String trimmed = name.trim();
224	        requireUnusedName(sheetId, id, trimmed);
225	        requireUnusedContact(sheetId, id, contact);
226	        person.setName(trimmed);
227	        boolean termsChanged = !Objects.equals(terms, person.getTerms());
228	        person.setTerms(terms);
229	        boolean contactChanged = !Objects.equals(contact, person.getContact());
230	        person.setContact(contact);
231	        LocalDate today = sheets.today(sheetId);
232	        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
233	            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
234	        }
235	        try {
236	            people.flush();
237	        } catch (DataIntegrityViolationException e) {
238	            throw inUse(e); // taken by another user at the same moment
239	        } catch (ObjectOptimisticLockingFailureException e) {
240	            throw savedByAnother(); // saved by another user at the same moment
241	        }
242	        record("PERSON_EDITED", sheetId, user, person, today,
243	                (termsChanged ? termsField(terms) : "") + (contactChanged ? contactField(contact) : ""));
244	        rollup.recordChanges(sheetId, user, before);
245	        return person;
246	    }
247	
248	    /** Give each of the people of {@code ids}, in list order, {@code grade} from {@code gradeFrom}
249	     *  (null: the sheet's today) as saving them in the person form would, each written with its
250	     *  PERSON_EDITED and rollup lines; all or none. Refused (404) when any is not on the sheet. */
251	    @Transactional
252	    public int grade(String sheetId, String user, List<Long> ids, String grade, LocalDate gradeFrom) {
253	        Set<Long> wanted = Set.copyOf(ids);
254	        List<Person> chosen = people.findBySheetIdOrderByIdAsc(sheetId).stream()
255	                .filter(p -> wanted.contains(p.getId())).toList();
256	        if (chosen.size() != wanted.size()) {
257	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person");
258	        }
259	        LocalDate today = sheets.today(sheetId);
260	        for (Person person : chosen) {
261	            RollupService.Snapshot before = rollup.snapshot(sheetId);
262	            if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
263	                person.recordGrade(grade, gradeFrom != null ? gradeFrom : today);
264	            }
265	            try {
266	                people.flush();
267	            } catch (ObjectOptimisticLockingFailureException e) {
268	                throw savedByAnother(); // saved by another user at the same moment
269	            }
270	            record("PERSON_EDITED", sheetId, user, person, today, "");
271	            rollup.recordChanges(sheetId, user, before);
272	        }
273	        return chosen.size();
274	    }
275	
276	    /** Retire a person from a date (a missing one takes the sheet's today); they count as retired
277	     *  at once. Retiring them again moves the date. From the day the date is reached their open
278	     *  claims, unless bound by a statement, leave the live totals. */
279	    @Transactional
280	    public Person retire(String sheetId, String user, long id, LocalDate from) {
281	        Person person = people.findForUpdate(id, sheetId)
282	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
283	        LocalDate on = from != null ? from : sheets.today(sheetId);
284	        RollupService.Snapshot before = rollup.snapshot(sheetId);
285	        person.setRetiredFrom(on);
286	        people.flush();
287	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
288	                + " name=" + person.getName() + " from=" + on);
289	        rollup.recordChanges(sheetId, user, before);
290	        return person;
291	    }
292	
293	    /** Add a hold to a person from a date (a missing one takes the sheet's today) to an optional
294	     *  one; their OPEN claims dated within it then count in no live total, unless bound by a
295	     *  statement. A to-date before the from-date is refused (422). */
296	    @Transactional
297	    public Person hold(String sheetId, String user, long id, LocalDate from, LocalDate to) {
298	        Person person = people.findForUpdate(id, sheetId)
299	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
300	        LocalDate on = from != null ? from : sheets.today(sheetId);
301	        if (to != null && to.isBefore(on)) {
302	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "The to-date is before the from-date");
303	        }
304	        RollupService.Snapshot before = rollup.snapshot(sheetId);
305	        person.addHold(on, to);
306	        people.flush();
307	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
308	                + " name=" + person.getName() + " from=" + on);
309	        rollup.recordChanges(sheetId, user, before);
310	        return person;
311	    }
312	
313	    /** Merge a person into another person on the sheet, as a steward: the merged person's claims
314	     *  move to the other (numbers and dates kept, listed after the other's in the order they were
315	     *  added, each unbound from any statement), their name and aliases become the other's aliases,
316	     *  their patrons are added to the other's (not the other themselves, no repeats), anyone naming
317	     *  them as patron names the other instead (no repeats), and their pool memberships move to the
318	     *  other (shares added where the other is a member already). Their statements, holds, watchers
319	     *  and contact go with them. Refused (404) for a person not on the sheet, (403) unless the user
320	     *  acts as a steward, (422) for the same person, either of them retired, or a pool share added
321	     *  past 100.00. */
322	    @Transactional
323	    public Person merge(String sheetId, String user, long id, long intoId) {
324	        Person from = people.findForUpdate(id, sheetId)
325	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
326	        Person into = people.findForUpdate(intoId, sheetId)
327	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
328	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
329	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may merge people");
330	        }
331	        if (from.getId().equals(into.getId())) {
332	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A person cannot be merged into themselves");
333	        }
334	        if (from.isRetired() || into.isRetired()) {
335	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A retired person cannot be merged");
336	        }
337	        RollupService.Snapshot before = rollup.snapshot(sheetId);
338	
339	        // pool memberships: moved, or the share added to the other's
340	        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
341	            var theirs = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
342	            if (theirs.isPresent()) {
343	                BigDecimal share = theirs.get().getShare().add(member.getShare());
344	                if (share.compareTo(BigDecimal.valueOf(100)) > 0) {
345	                    throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
346	                            "The merged shares would be over 100.00 in a pool");
347	                }
348	                theirs.get().setShare(share);
349	                poolMembers.delete(member);
350	            } else {
351	                member.setPersonId(into.getId());
352	            }
353	        }
354	        poolMembers.flush();
355	
356	        // claims: moved, listed after the other's in the order they were added, unbound
357	        long listed = claims.findLastListed(sheetId);
358	        List<Claim> moved = claims.findByPersonForUpdate(from.getId(), sheetId).stream()
359	                .sorted(Comparator.comparing(Claim::getId)).toList();
360	        for (Claim claim : moved) {
361	            claim.setPersonId(into.getId());
362	            claim.setListed(++listed);
363	            claim.unbind();
364	        }
365	        claims.flush();
366	
367	        // patrons: the merged person's added to the other's; those naming the merged person name the other
368	        Set<Long> intoPatrons = new LinkedHashSet<>(patronIds(into.getId()));
369	        List<PersonPatron> theirPatrons = patrons.findByPersonIdOrderByIdAsc(from.getId());
370	        List<PersonPatron> namingThem = patrons.findByPatronIdOrderByIdAsc(from.getId());
371	        for (PersonPatron named : theirPatrons) {
372	            if (!named.getPatronId().equals(into.getId()) && intoPatrons.add(named.getPatronId())) {
373	                patrons.save(new PersonPatron(sheetId, into.getId(), named.getPatronId()));
374	            }
375	        }
376	        for (PersonPatron naming : namingThem) {
377	            if (!naming.getPersonId().equals(into.getId())
378	                    && !naming.getPersonId().equals(from.getId())
379	                    && !patrons.existsByPersonIdAndPatronId(naming.getPersonId(), into.getId())) {
380	                patrons.save(new PersonPatron(sheetId, naming.getPersonId(), into.getId()));
381	            }
382	        }
383	        patrons.deleteAll(theirPatrons);
384	        patrons.deleteAll(namingThem);
385	        patrons.flush();
386	
387	        // statements and watchers go with them
388	        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from.getId()));
389	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
390	        statements.flush();
391	        watches.flush();
392	
393	        String fromName = from.getName();
394	        List<String> fromAliases = from.getAliases();
395	        people.delete(from);
396	        people.flush();
397	        into.addAlias(fromName);
398	        fromAliases.forEach(into::addAlias);
399	        try {
400	            people.flush();
401	        } catch (ObjectOptimisticLockingFailureException e) {
402	            throw savedByAnother(); // saved by another user at the same moment
403	        }
404	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + fromName
405	                + " into=" + into.getName());
406	        rollup.recordChanges(sheetId, user, before);
407	        return into;
408	    }
409	
410	    /** Written with the grade in force on {@code today}, the sheet's today, then {@code extra}. */
411	    private void record(String event, String sheetId, String user, Person person, LocalDate today, String extra) {
412	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
413	                + " name=" + person.getName() + " grade=" + person.gradeOn(today) + extra);
414	    }
415	
416	    /** The terms field of a person's record: the days, empty when none. */
417	    private static String termsField(Integer terms) {
418	        return " terms=" + (terms == null ? "" : terms);
419	    }
420	
421	    /** The contact field of a person's record: the contact, empty when none. */
422	    private static String contactField(String contact) {
423	        return " contact=" + (contact == null ? "" : contact);
424	    }
425	
426	    /** Refuse a contact another person on the sheet already has; none is never refused. */
427	    private void requireUnusedContact(String sheetId, Long exceptId, String contact) {
428	        if (contact == null) {
429	            return;
430	        }
431	        boolean taken = people.findBySheetIdAndContact(sheetId, contact).stream()
432	                .anyMatch(p -> !p.getId().equals(exceptId));
433	        if (taken) {
434	            throw contactInUse();
435	        }
436	    }
437	
438	    /** A unique name or contact taken by another user at the same moment. */
439	    private static ResponseStatusException inUse(DataIntegrityViolationException e) {
440	        String message = String.valueOf(e.getMostSpecificCause().getMessage()).toUpperCase(java.util.Locale.ROOT);
441	        return message.contains("PERSON_SHEET_CONTACT") ? contactInUse() : nameInUse();
442	    }
443	
444	    /** Refuse a name another person on the sheet already has as their name or an alias (ignoring
445	     *  case); {@code exceptId} null checks against everyone, the person's own name and aliases too. */
446	    private void requireUnusedName(String sheetId, Long exceptId, String name) {
447	        boolean taken = people.findBySheetIdAndNameIgnoreCase(sheetId, name).stream()
448	                .anyMatch(p -> !p.getId().equals(exceptId))
449	                || !people.findBySheetIdAndAliasIgnoreCase(sheetId, name).isEmpty();
450	        if (taken) {
451	            throw nameInUse();
452	        }
453	    }
454	
455	    private static ResponseStatusException savedByAnother() {
456	        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Saved by someone else since it was loaded");
457	    }
458	
