34	@RestController
35	@RequestMapping("/api/sheets/{sheetId}/people")
36	@Validated
37	public class PersonController {
38	
39	    /** A person as the screen shows them, with their statement count and their last statement's
40	     *  due-total (two decimals; null when it was n/a or they have none) and date, and the date
41	     *  they are retired from (null while not retired), whether they have any hold, their holds, and the ids of
42	     *  their patrons in the order they were named, and whether the signed-in user watches them. The grade is the one in force on the sheet's
43	     *  today; grades lists every grade they have been given, by from-date, the first one undated; terms
44	     *  are their own terms in days (null when they have none). */
45	    public record PersonView(long id, String name, String grade, long version, int statementCount,
46	            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held, List<Person.Hold> holds,
47	            List<Long> patronIds, List<Person.DatedGrade> grades, boolean watched, Integer terms,
48	            String contact, List<String> aliases) {
49	        public static PersonView of(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
50	                boolean watched) {
51	            return of(p.getId(), p, today, s, patronIds, watched);
52	        }
53	
54	        /** The person of the id, which a version rebuilt from the sheet's history does not carry. */
55	        static PersonView of(long id, Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
56	                boolean watched) {
57	            return new PersonView(id, p.getName(), p.gradeOn(today), p.getVersion(), s.count(),
58	                    s.lastDueTotal() == null ? null : s.lastDueTotal().setScale(2).toPlainString(), s.lastDate(),
59	                    p.getRetiredFrom(), p.isHeld(), p.getHolds(), patronIds, p.getGrades(), watched, p.getTerms(),
