package net.officefloor.hq.app.claim;


/** A line of a claim's status log: a status it took, who moved it there, the sheet's today then
 *  and its due as computed at that moment (none: n/a). */
@Entity
@Table(name = "claim_log")
public class ClaimLog {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String by;

    @Column(name = "on_date", nullable = false)
    private LocalDate on;

    @Column(name = "due", precision = 15, scale = 2)
    private BigDecimal due;

    protected ClaimLog() {
    }

    public ClaimLog(String sheetId, Long claimId, ClaimStatus status, String by, LocalDate on, BigDecimal due) {
        this.sheetId = sheetId;
        this.claimId = claimId;
        this.status = status;
        this.by = by;
        this.on = on;
        this.due = due;
    }

    public Long getClaimId() {
        return claimId;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getBy() {
        return by;
    }

    public LocalDate getOn() {
        return on;
    }

    public BigDecimal getDue() {
        return due;
    }
}
package net.officefloor.hq.app.claim;


public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims as they are listed: newest (or most recently reassigned) first. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    /** The highest place a claim on the sheet is listed at; 0 with none. */
    @Query("select coalesce(max(c.listed), 0) from Claim c where c.sheetId = :sheetId")
    long findLastListed(String sheetId);

    /** The number of the sheet's last bulk settle batch; 0 with none. */
    @Query("select coalesce(max(c.batch), 0) from Claim c where c.sheetId = :sheetId")
    int findLastBatch(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

