private String correctedBy(String sheetId, long personId, BigDecimal amount, String corrects) {
    if (amount.signum() >= 0) {
        return null;
    }
    if (corrects == null
            || !claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
