CREATE TABLE claim_log (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    status    VARCHAR(10)    NOT NULL CHECK (status IN ('DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID')),
    by_user   VARCHAR(100)   NOT NULL,
    on_date   DATE           NOT NULL,
    due       DECIMAL(15, 2)
);
CREATE INDEX claim_log_sheet ON claim_log (sheet_id, id);
CREATE INDEX claim_log_claim ON claim_log (claim_id, id);
CREATE TABLE claim_comment (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    claim_id  BIGINT         NOT NULL REFERENCES claim (id),
    by_user   VARCHAR(100)   NOT NULL,
    on_date   DATE           NOT NULL,
    text      VARCHAR(1000)  NOT NULL
);
CREATE INDEX claim_comment_sheet ON claim_comment (sheet_id, id);
CREATE INDEX claim_comment_claim ON claim_comment (claim_id, id);
-- over time. Only their OPEN claims dated within a hold (and not bound by a statement) are left out
-- of the live totals. A person held before keeps a hold from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    position  INT    NOT NULL,
    from_date DATE   NOT NULL,
    to_date   DATE,
    CHECK (to_date IS NULL OR to_date >= from_date),
    PRIMARY KEY (person_id, position)
);
INSERT INTO person_hold (person_id, position, from_date, to_date)
    SELECT id, 0, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
CREATE TABLE person_patron (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    patron_id BIGINT       NOT NULL REFERENCES person (id),
    CHECK (patron_id <> person_id),
    CONSTRAINT person_patron_once UNIQUE (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron (sheet_id, id);
CREATE TABLE person_statement (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    due_total  DECIMAL(15, 2),
    claims     INT            NOT NULL,
    taken_on   DATE           NOT NULL,
    taken_by   VARCHAR(100)   NOT NULL
);
CREATE INDEX person_statement_person ON person_statement (person_id, id);
-- A statement binds each claim of the person that counts then to the due it shows then: the claim
-- shows and totals that figure (null: n/a) until the person's next statement rebinds it, or leaves
-- it unbound (live again) when it no longer counts. A settled claim's fixed due still wins.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL,
    CONSTRAINT person_watch_once UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
CREATE TABLE claim (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id  BIGINT         NOT NULL REFERENCES person (id),
    amount     DECIMAL(15, 2) NOT NULL CHECK (amount >= 0),
    claim_date DATE           NOT NULL,
    note       VARCHAR(1000)  NOT NULL DEFAULT ''
);
CREATE INDEX claim_sheet ON claim (sheet_id, id);
CREATE INDEX claim_person ON claim (person_id, id);
-- beginning of time, and each later grade is kept here from its from-date (one per from-date). A
-- claim uses the grade in force on its date: the one with the latest from-date on or before it.
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE       NOT NULL,
    grade     VARCHAR(1) NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    PRIMARY KEY (person_id, from_date)
);
-- when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    due_total DECIMAL(15, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
